/* Opt-in, local-only scroll observations. No storage and no outbound requests. */
(() => {
 if(new URL(location.href).searchParams.get('diagnostics')!=='1')return;
 const panel=document.createElement('aside');panel.setAttribute('aria-label','Local scroll diagnostics');panel.style.cssText='position:fixed;z-index:1000;left:8px;right:8px;bottom:8px;max-width:480px;padding:9px 11px;background:#020b18ee;border:1px solid #6aa894;color:#ceffe7;font:11px/1.35 ui-monospace,monospace;pointer-events:none';
 const text=document.createElement('pre');text.style.cssText='margin:0;white-space:pre-wrap';const copy=document.createElement('button');copy.type='button';copy.textContent='Copy local report';copy.style.cssText='pointer-events:auto;color:#fff;background:#183c3b;padding:8px 12px;margin-top:6px;font:12px Arial,sans-serif;border:1px solid #75a49a;border-radius:0';panel.append(text,copy);document.body.append(panel);
 let timer=0,lastInput='none',touches=0,moves=0,report='',maxRoot=0,maxScene=0,maxVisual=0;
 const round=n=>Math.round((n||0)*10)/10;
 function update(){timer=0;const j=document.querySelector('#journey'),scene=document.querySelector('.scene'),v=window.visualViewport,d=document.documentElement,root=window.scrollY,st=scene.getBoundingClientRect().top,vt=v?.offsetTop||0;maxRoot=Math.max(maxRoot,Math.abs(root));maxScene=Math.max(maxScene,Math.abs(st));maxVisual=Math.max(maxVisual,Math.abs(vt));
  const data={build:new URL(document.querySelector('script[src*="journey.js"]').src).searchParams.get('v'),scrollLayout:d.dataset.scrollLayout,journeyContainingBlock:j.offsetParent?.tagName,urlMode:new URL(location.href).searchParams.get('view')||'portal',activeMode:document.body.classList.contains('reduced')?'reading':'portal',browser:navigator.userAgent,viewport:[innerWidth,innerHeight],smallViewport:document.querySelector('#viewport-unit').clientHeight,visualViewport:v?{height:round(v.height),offsetTop:round(v.offsetTop),pageTop:round(v.pageTop),scale:v.scale}:null,documentScroll:round(root),rootScroll:round(document.scrollingElement.scrollTop),journeyScroll:round(j.scrollTop),journeyMax:round(j.scrollHeight-j.clientHeight),journeyRect:j.getBoundingClientRect().toJSON(),sceneRect:scene.getBoundingClientRect().toJSON(),phase:document.querySelector('#world').dataset.phase,lastInput,touches,moves,maxRoot,maxScene,maxVisual,scrollStyles:{html:getComputedStyle(d).overflow,body:getComputedStyle(document.body).position,journey:getComputedStyle(j).overflow,scene:getComputedStyle(scene).position}};
  report=JSON.stringify(data,null,2);text.textContent=`LOCAL SCROLL TEST · v${data.build} · ${data.activeMode}\nView ${innerWidth}×${innerHeight} / small ${data.smallViewport}\nRoot ${round(root)} · Journey ${round(j.scrollTop)} / ${data.journeyMax}\nScene top ${round(st)} · Visual top ${round(vt)} · height ${round(v?.height)}\nMax offsets root ${round(maxRoot)} / scene ${round(maxScene)} / visual ${round(maxVisual)}\nTouch starts ${touches} · moves ${moves}\nLast ${lastInput}`;
 }
 const queue=()=>{if(!timer)timer=setTimeout(update,80);};
 document.addEventListener('touchstart',e=>{touches++;lastInput='touch on '+(e.target.closest('[id]')?.id||e.target.tagName);queue();},{passive:true,capture:true});document.addEventListener('touchmove',()=>{moves++;queue();},{passive:true,capture:true});document.addEventListener('scroll',e=>{lastInput='scroll '+(e.target.id||e.target.tagName||'document');queue();},{passive:true,capture:true});window.addEventListener('resize',queue,{passive:true});
 window.visualViewport?.addEventListener('resize',queue,{passive:true});window.visualViewport?.addEventListener('scroll',queue,{passive:true});
 copy.addEventListener('click',async()=>{update();try{await navigator.clipboard.writeText(report);copy.textContent='Report copied';}catch{copy.textContent='Select the report below';text.textContent=report;panel.style.pointerEvents='auto';text.style.maxHeight='45vh';text.style.overflow='auto';}});update();
})();
